Translate("frFR", "darkshore", {
	title = "Sombrivage",
	sections = {
		{
			title = "Résumé",
			text = [=[Sombrivage est une longue côte grise au nord-ouest de {link:kalimdor}Kalimdor{/link}, de l'autre côté d'un étroit bras de mer face au grand arbre {link:teldrassil}Teldrassil{/link}. Ses forêts sont sombres même à midi, ses plages sont froides, et ses collines sont pleines de ruines plus anciennes que tout royaume des hommes. Les {link:night-elves}elfes de la nuit{/link} la tiennent depuis la petite ville portuaire d'{link:auberdine}Auberdine{/link}. Ils en ont fait une porte entre leur nouveau foyer et le reste du monde. Pourtant, la terre qu'ils gardent est malade. Ses rivières sont souillées, ses bêtes sont devenues folles, et de vieux ennemis sont revenus dans les ruines du propre passé des elfes.]=],
		},
		{
			title = "Origines",
			text = [=[Bien avant la {link:great-sundering}Fracture{/link}, ces collines dominaient les rives du {link:well-of-eternity}puits d'Éternité{/link}. Ici, la {link:queen-azshara}reine Azshara{/link} éleva les villes jumelles d'{link:ameth-aran}Ameth’Aran{/link} et de {link:bashal-aran}Bashal'Aran{/link} pour ses Bien-nés favoris, et chargea le seigneur {link:athrikus-narassin}Athrikus Narassin{/link} de les gouverner depuis sa {link:tower-of-althalaxx}Tour d'Althalaxx{/link}. Quand la {link:war-of-the-ancients}guerre des Anciens{/link} prit fin et que le Puits fut détruit, les villes tombèrent et la terre fut déchirée. Ce qui en resta devint une côte de la nouvelle mer. Les ruines de {link:ruins-of-mathystra}Mathystra{/link}, jadis un grand bastion des elfes, s'effritèrent dans le nord. Après la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, les elfes de la nuit élevèrent {link:teldrassil}Teldrassil{/link} au large de cette côte. Aucune chronique ne rapporte l'année où {link:auberdine}Auberdine{/link} fut bâtie.]=],
		},
		{
			title = "De nos jours",
			text = [=[{link:auberdine}Auberdine{/link} est une humble ville, mais elle est affairée. Des navires transportent les voyageurs vers {link:teldrassil}Teldrassil{/link} et, de l'autre côté de la mer, vers les terres des humains. Un nouveau navire la relie désormais au {link:stormwind-harbor}port de Stormwind{/link}, et un autre fait voile vers le {link:menethil-harbor}Port de Menethil{/link} en passant par {link:southshore}Southshore{/link}. La ville a besoin de chaque ami que ces navires peuvent amener. Les {link:furbolgs}furbolgs{/link} {link:blackwood-furbolgs}Noirbois{/link} se sont retournés contre les elfes. Une maladie se répand parmi les ours des chardons et les cerfs, et elle semble couler depuis le {link:felwood}Gangrebois{/link}, à l'est. Des {link:naga}nagas{/link} tiennent les ruines de {link:ruins-of-mathystra}Mathystra{/link}. Le {link:twilight-s-hammer}Marteau du crépuscule{/link} creuse au {link:the-master-s-glaive}Glaive du Maître{/link}, et un culte de démonistes se rassemble à la {link:tower-of-althalaxx}Tour d'Althalaxx{/link}. Quand l'ancien d'Auberdine demanda de l'aide à {link:stormwind-city}Stormwind{/link}, Stormwind n'en avait aucune à offrir. {link:darnassus}Darnassus{/link} n'en a guère envoyé davantage.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les elfes de la nuit d'{link:auberdine}Auberdine{/link}.{/b} {link:sentinels}Sentinelles{/link}, druides et érudits qui tiennent la ville et étudient la corruption qui l'entoure.
• {b}Les nains.{/b} Mineurs, forgerons et marchands venus d'{link:ironforge}Ironforge{/link}, et les érudits de la {link:explorers-league}Ligue des explorateurs{/link}, qui creusent dans le sud.
• {b}Les furbolgs {link:blackwood-furbolgs}Noirbois{/link}.{/b} Jadis amis des elfes, désormais rendus fous et hostiles dans leurs camps.
• {b}Les nagas.{/b} Les nagas Stormscale hantent {link:ruins-of-mathystra}Mathystra{/link} et la grotte derrière les {link:cliffspring-falls}Chutes de la Bondissante{/link}.
• {b}Les murlocs Greymist.{/b} Ils se pressent sur la côte et s'en prennent aux navires et aux pêcheurs.
• {b}Les morts sans repos.{/b} Les esprits des Bien-nés errent encore dans les ruines d'{link:ameth-aran}Ameth’Aran{/link}.
• {b}Les séléniens.{/b} Ils parcourent les collines de l'est, et deviennent plus hostiles à chaque saison.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les villes jumelles.{/b} À l'époque d'{link:azshara}Azshara{/link}, {link:ameth-aran}Ameth’Aran{/link} et {link:bashal-aran}Bashal'Aran{/link} prospéraient près du puits d'Éternité, tandis que le monde sous elles glissait vers la folie.
• {b}La {link:great-sundering}Fracture{/link}.{/b} Dans le chaos de la guerre, {link:athrikus-narassin}Athrikus Narassin{/link} promit au peuple d'Ameth’Aran la vie éternelle par sa magie. Leurs esprits n'ont jamais trouvé le repos.
• {b}Le long sommeil.{/b} Beaucoup de druides suivirent {link:malfurion-stormrage}Malfurion Stormrage{/link} dans le sommeil du {link:emerald-dream}Rêve d'émeraude{/link}. Certains de ces dormeurs se sont récemment éveillés, et ils trouvent leurs anciennes demeures en ruine.
• {b}Le nouveau foyer.{/b} Après la guerre contre la {link:burning-legion}Légion ardente{/link}, les elfes de la nuit firent de {link:teldrassil}Teldrassil{/link} leur foyer, et {link:auberdine}Auberdine{/link} devint sa porte sur le monde.]=],
		},
		{
			title = "Récits du rivage",
			text = [=[• De grandes créatures marines s'échouent en nombre croissant sur les plages de Sombrivage. Les prêtresses du temple de la Lune ont appris que ce sont les nagas qui les chassent.
• Un cristal rouge se dresse dans les collines de l'est. À l'intérieur reposent des fragments d'os et la moitié d'une mâchoire. Les séléniens se rassemblent autour de lui, et nul ne sait pourquoi.
• Les pêcheurs d'{link:auberdine}Auberdine{/link} ne sortent plus leurs bateaux. Ils disent que les murlocs ont mangé tous les mérous.]=],
		},
	},
})

Translate("frFR", "auberdine", {
	title = "Auberdine",
	sections = {
		{
			title = "Résumé",
			text = [=[Auberdine est la ville portuaire de {link:darkshore}Sombrivage{/link}, bâtie sur la côte face à {link:teldrassil}Teldrassil{/link}. Son ancien, {link:thundris-windweaver}Thundris Windweaver{/link}, et son conseil de village la gouvernent. Des {link:sentinels}Sentinelles{/link} la gardent, et un puits de lune en son cœur donne l'eau pure dont ses druides et ses prêtresses ont besoin. {link:night-elves}Elfes de la nuit{/link} et nains partagent son auberge, ses forges et ses quais. De ses jetées, un navire traverse jusqu'à {link:rut-theran-village}Rut'theran{/link}, au pied de Teldrassil, et un autre fait voile vers le {link:menethil-harbor}Port de Menethil{/link}. Deux nouvelles routes sont désormais venues : l'une vers le {link:stormwind-harbor}port de Stormwind{/link}, et l'autre vers Menethil en passant par {link:southshore}Southshore{/link}, dans les {link:hillsbrad-foothills}Contreforts d'Hillsbrad{/link}. La ville espère que les navires apporteront de l'aide. Jusqu'ici, ils n'ont apporté que des voyageurs.]=],
		},
	},
})

Translate("frFR", "ruins-of-mathystra", {
	title = "Ruines de Mathystra",
	aliases = { "Mathystra" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Ruines de Mathystra se trouvent à l'extrême nord-est de {link:darkshore}Sombrivage{/link}. Mathystra fut jadis un grand bastion des elfes, et des fragments de sa magie gisent encore parmi l'herbe et les pierres brisées. Les {link:naga}nagas{/link} Stormscale la tiennent désormais, et ils pillent le lieu que leurs propres ancêtres appelaient jadis leur foyer. Leurs dresseuses plient les grandes bêtes de la mer à leur volonté. Depuis peu, quelque chose de plus ancien a été découvert sous les ruines. Un gardien élémentaire veillait sur un escalier qui descend dans les ténèbres, et même les Anciens ne savent pas encore ce qui se trouve en bas.]=],
		},
	},
})

Translate("frFR", "bashal-aran", {
	title = "Bashal'Aran",
	sections = {
		{
			title = "Résumé",
			text = [=[Bashal'Aran était l'une des villes jumelles que la reine {link:azshara}Azshara{/link} éleva pour ses Bien-nés. Ses ruines se trouvent à l'est d'{link:auberdine}Auberdine{/link}. Des lutins démoniaques, des grells et des satyres de la bande Deth'ryll en ont fait leur repaire, et ils se renforcent en se nourrissant de la magie qui s'accroche encore aux pierres. Il existe pourtant un sanctuaire, sur un promontoire à l'ouest des ruines, dont ils n'osent approcher. Une lumière bleue flotte autour de lui. À l'intérieur attend l'esprit d'{link:asterion}Asterion{/link}, lié là par son propre maître depuis plus longtemps qu'aucun elfe vivant ne peut s'en souvenir.]=],
		},
	},
})

Translate("frFR", "ameth-aran", {
	title = "Ameth’Aran",
	sections = {
		{
			title = "Résumé",
			text = [=[Ameth’Aran était la jumelle de {link:bashal-aran}Bashal'Aran{/link}, une ville des Bien-nés près du puits d'Éternité. Elle fut ruinée dans la guerre qui déchira le monde. Son peuple ne mourut pas vraiment. Il s'accrocha à la promesse d'{link:athrikus-narassin}Athrikus Narassin{/link}, et il erre aujourd'hui dans les ruines sous la forme d'esprits maudits et gémissants, portant encore les outils magiques de leur ancien art. Deux grandes tablettes parmi les pierres racontent l'histoire de la ville et de sa chute. Une antique flamme bleue brûle encore ici. Elle est assez chaude pour détruire des choses qu'aucun autre feu ne peut toucher.]=],
		},
	},
})

Translate("frFR", "tower-of-althalaxx", {
	title = "Tour d'Althalaxx",
	sections = {
		{
			title = "Résumé",
			text = [=[La Tour d'Althalaxx s'élève au nord-est de {link:darkshore}Sombrivage{/link}. Ce fut le siège d'{link:athrikus-narassin}Athrikus Narassin{/link}, le seigneur Bien-né qui gouvernait {link:ameth-aran}Ameth’Aran{/link} et {link:bashal-aran}Bashal'Aran{/link} pour la reine {link:azshara}Azshara{/link} et passait ici la plupart de ses jours, loin d'elles. Après dix mille ans, la tour a de nouveau un maître. Une compagnie de démonistes qui se fait appeler {link:cult-of-the-dark-strand}Cult of the Dark Strand{/link} s'en est emparée, et les plus puissants d'entre eux se tiennent dans les salles du haut. Un guetteur d'{link:auberdine}Auberdine{/link}, {link:balthule-shadowstrike}Balthule Shadowstrike{/link}, a établi son camp non loin. Il a vu des éclairs de lumière au sommet de la tour, et entendu des cris.]=],
		},
	},
})

Translate("frFR", "grove-of-the-ancients", {
	title = "Bosquet des Anciens",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bosquet des Anciens se trouve au sud de {link:darkshore}Sombrivage{/link}, abrité par les montagnes. Ici demeurent les Anciens, grands esprits de la forêt qui se tiennent aux côtés des elfes de la nuit depuis les jours les plus reculés. {link:onu}Onu{/link}, un Ancien du savoir, recueille des nouvelles de chaque menace dans le pays, et les druides d'{link:auberdine}Auberdine{/link} écoutent ses avertissements. À ses côtés se tient {link:arbal}Arbal{/link}, un Ancien de guerre. Le bosquet est patient, comme le sont tous les Anciens, mais il n'est pas inactif. C'est ici que se prépare discrètement la lutte contre les nagas et le {link:twilight-s-hammer}Marteau du crépuscule{/link}.]=],
		},
	},
})

Translate("frFR", "twilight-vale", {
	title = "Vallée du crépuscule",
	sections = {
		{
			title = "Résumé",
			text = [=[La Vallée du crépuscule est le nom donné aux bois du sud de {link:darkshore}Sombrivage{/link}, depuis les ruines d'{link:ameth-aran}Ameth’Aran{/link} jusqu'aux frontières d'{link:ashenvale}Orneval{/link}. Ses routes relient {link:auberdine}Auberdine{/link} au {link:maestra-s-post}Poste de Maestra{/link} et à {link:astranaar}Astranaar{/link}, et les messagers qui les empruntent le font à leurs risques et périls. Des furbolgs {link:blackwood-furbolgs}Noirbois{/link} tendent des embuscades aux voyageurs, des rôdeurs de lune rôdent parmi les arbres, et les ours malades de la forêt attaquent quiconque approche. Le {link:grove-of-the-ancients}Bosquet des Anciens{/link}, le {link:the-master-s-glaive}Glaive du Maître{/link} et les fouilles de la {link:explorers-league}Ligue des explorateurs{/link} se trouvent tous dans la vallée. Ceux qui la traversent restent sur la route.]=],
		},
	},
})

Translate("frFR", "mist-s-edge", {
	title = "La lisière des brumes",
	sections = {
		{
			title = "Résumé",
			text = [=[La lisière des brumes est la longue étendue d'eau grise le long de la côte de {link:darkshore}Sombrivage{/link}, là où la Bondissante se jette dans la mer. Ses plages sont jonchées de carcasses de grandes créatures marines et d'épaves de navires. Deux de ces navires, le Silver Dawning et le Mist Veil, gisent au fond au nord d'{link:auberdine}Auberdine{/link}, coulés par des murlocs alors qu'ils entraient au port. Des crabes courent sur chaque bande de sable. Les murlocs Greymist dressent leurs huttes le long du rivage, et leurs chefs chassent aussi bien les pêcheurs que les {link:sentinels}Sentinelles{/link}.]=],
		},
	},
})

Translate("frFR", "cliffspring-river", {
	title = "La Bondissante",
	sections = {
		{
			title = "Résumé",
			text = [=[La Bondissante descend des montagnes de l'est et court jusqu'à la mer au nord d'{link:auberdine}Auberdine{/link}. Un pont l'enjambe au-dessus de sa première cascade. Son eau était jadis pure. Elle devient aujourd'hui souillée, et l'ancien d'Auberdine craint que la souillure n'atteigne la ville elle-même. Les camps du nord des furbolgs {link:blackwood-furbolgs}Noirbois{/link} se dressent sur ses rives, et leurs feux brûlent au bord de l'eau. {link:thundris-windweaver}Thundris Windweaver{/link} croit que les furbolgs souillent la rivière, mais que la vraie racine du poison se trouve plus à l'est, dans le {link:felwood}Gangrebois{/link}.]=],
		},
	},
})

Translate("frFR", "cliffspring-falls", {
	title = "Chutes de la Bondissante",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Chutes de la Bondissante dévalent des montagnes à l'est d'{link:auberdine}Auberdine{/link}. La plus grande partie de la région y boit, et un poison coule désormais dans leurs eaux et rend malades les cerfs de {link:darkshore}Sombrivage{/link}. Derrière les chutes se trouve une grotte où poussent des champignons rares. Les Anciens avertirent les gens d'Auberdine de s'en tenir éloignés, car ils sentaient qu'un nouveau mal y avait élu domicile. Ils avaient raison. Les nagas ont pris la grotte, et un seigneur {link:naga}naga{/link} appelé {link:lord-sinslayer}Sinslayer{/link} les commande.]=],
		},
	},
})

Translate("frFR", "blackwood-den", {
	title = "Tanière des Noirbois",
	sections = {
		{
			title = "Résumé",
			text = [=[La Tanière des Noirbois se trouve à l'extrême sud de {link:darkshore}Sombrivage{/link}, près de la frontière d'{link:ashenvale}Orneval{/link}. C'est un ensemble de camps de furbolgs autour d'une petite grotte, et elle appartient à la {link:blackwood-furbolgs}tribu Noirbois{/link}. Un {link:night-elves}elfe de la nuit{/link} nommé {link:volcor}Volcor{/link} y fut blessé par les furbolgs et se réfugia au fond de la grotte. Son fidèle compagnon, {link:grimclaw}Grimclaw{/link}, partit seul vers le nord chercher de l'aide. La tanière est un sombre signe de la déchéance des furbolgs. Ils vivaient jadis en paix avec les elfes. Ils attaquent désormais tout elfe qui s'égare près de leurs feux.]=],
		},
	},
})

Translate("frFR", "remtravel-s-excavation", {
	title = "Excavations de Remtravel",
	aliases = { "fouilles de Remtravel" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Excavations de Remtravel sont le chantier de fouilles de la {link:explorers-league}Ligue des explorateurs{/link} au sud-ouest de {link:darkshore}Sombrivage{/link}. Ici, le prospecteur {link:prospector-remtravel}Remtravel{/link} et son équipe mirent au jour les signes d'une grande et antique société. Puis le sol lui-même se retourna contre eux. Des golems de pierre surgirent de la terre et envahirent le site, et les {link:troggs}troggs{/link} Gravelflint vinrent avec eux. L'équipe s'enfuit à {link:auberdine}Auberdine{/link}. Pas le prospecteur. Il est toujours quelque part sur le chantier, à la recherche d'un mystérieux fossile qu'il a déjà perdu une fois. Ce que la Ligue fera du fossile, nul à Auberdine ne saurait le dire.]=],
		},
	},
})

Translate("frFR", "the-master-s-glaive", {
	title = "Le Glaive du Maître",
	aliases = { "Glaive du Maître" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Glaive du Maître se dresse au sud de {link:darkshore}Sombrivage{/link} : une lame immense plantée dans le crâne d'un géant tombé. {link:onu}Onu{/link} enseigne que l'un des anciens seigneurs de la terre mourut ici en des âges reculés, empalé par le glaive. Le seigneur est mort depuis longtemps, mais des éclats de sa puissance demeurent peut-être dans ses os. Le {link:twilight-s-hammer}Marteau du crépuscule{/link} est venu les chercher. Ses cultistes campent sous la lame, et leurs livres contiennent des pages d'antique magie elfique détournée pour rappeler leurs anciens maîtres dans le monde.]=],
		},
	},
})

Translate("frFR", "thundris-windweaver", {
	title = "Thundris Windweaver",
	subtitle = "Ancien d'Auberdine",
	found = "Auberdine, à l'étage de l'hôtel de ville",
	hint = [=[Cherchez l'ancien qui gère les affaires quotidiennes d'Auberdine.]=],
	allegiance = "Auberdine · Elfes de la nuit",
	aliases = { "Thundris" },
	sections = {
		{
			title = "Résumé",
			text = [=[Thundris Windweaver est l'ancien d'{link:auberdine}Auberdine{/link}. Il mène les affaires quotidiennes de la ville d'une main juste et ferme. Il est aussi son plus fin connaisseur de la corruption. Il a déjà vu cette maladie, en des temps très anciens, et il sait qu'elle ne s'arrête pas aux lisières d'une forêt.]=],
		},
		{
			title = "Importance",
			text = [=[Thundris voit toute la forme du mal de {link:darkshore}Sombrivage{/link}. La rage des furbolgs, la rivière souillée et les outils des anciens Bien-nés sont, pour lui, les parties d'une même guerre. Il veut aussi qu'{link:auberdine}Auberdine{/link} soit connue. Les grandes cités ne se souviennent que de ce que la {link:great-sundering}Fracture{/link} a pris aux elfes de la nuit. Il voudrait qu'elles se souviennent de la ville qui se dresse encore.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il remonta l'empoisonnement de la Bondissante jusqu'au {link:felwood}Gangrebois{/link}.
• Il apprit que les satyres corrompent les furbolgs {link:blackwood-furbolgs}Noirbois{/link} au moyen de talismans.
• Il fait rassembler et détruire les reliques magiques des Bien-nés d'{link:ameth-aran}Ameth’Aran{/link}.
• Il purifie les gemmes de Kor prises aux nagas pour ceux qui suivent une voie sacrée.
• Il écrivit à {link:stormwind-city}Stormwind{/link} pour demander de l'aide.]=],
		},
	},
	chapters = {
		{
			title = "Les Noirbois corrompus",
			hint = [=[Attirez au-dehors le satyre qui tourmente les furbolgs du nord.]=],
			text = [=[Thundris mêla de l'eau du puits de lune à la nourriture des furbolgs et la fit déposer près de leur feu. Ceux qui en mangèrent furent purifiés un instant. En cet instant, le {link:satyrs}satyre{/link} qui les tenait asservis sortit voir ce qui n'allait pas. Son talisman fut rapporté à {link:auberdine}Auberdine{/link}. Thundris parla d'une bataille gagnée dans une longue guerre.]=],
		},
		{
			title = "Les outils des Bien-nés",
			hint = [=[Prenez les reliques des anciens Bien-nés aux esprits d'Ameth’Aran.]=],
			text = [=[Les esprits d'{link:ameth-aran}Ameth’Aran{/link} portent encore les instruments de leur magie. Thundris aurait voulu qu'ils périssent dans le cataclysme qui mit fin à leur monde. Puisqu'il n'en fut rien, il les détruira lui-même.]=],
		},
		{
			title = "Une lettre par-delà la mer",
			hint = [=[Portez la lettre de l'ancien à Stormwind et rapportez sa réponse.]=],
			text = [=[Thundris envoya une lettre à {link:baros-alexston}Baros Alexston{/link}, de {link:stormwind-city}Stormwind{/link}, à bord du nouveau navire. La réponse fut aimable, et elle fut vide. Stormwind n'avait rien à offrir. Thundris l'accepta sans bruit. Si ni Stormwind ni {link:darnassus}Darnassus{/link} ne veulent venir, dit-il, alors {link:auberdine}Auberdine{/link} décidera de son propre sort.]=],
		},
	},
	mentions = {
		{
			text = [=[Thundris Windweaver, envoyé par {link:terenthis}Terenthis{/link}]=],
		},
		{ text = "{link:bashal-aran}Bashal'Aran{/link}" },
		{ text = "{link:cliffspring-river}La Bondissante{/link}" },
		{ text = "À la recherche de la gemme de Kor" },
		{ text = "Élargir les horizons" },
		{ text = "Tout n'est que jeu jusqu'à ce que..., un œil d'un mal ancien" },
	},
	bonds = {
		{ id = "terenthis", name = "Terenthis", note = "lui envoie des nouvelles des furbolgs" },
