Translate("frFR", "terenthis", {
	title = "Terenthis",
	subtitle = "Guetteur des Noirbois",
	found = "Auberdine, près du poste des Sentinelles",
	hint = [=[Parlez à l'elfe de la nuit d'Auberdine qui traque les signes de la corruption.]=],
	allegiance = "Auberdine · Elfes de la nuit",
	sections = {
		{
			title = "Résumé",
			text = [=[Terenthis est un {link:night-elves}elfe de la nuit{/link} d'{link:auberdine}Auberdine{/link} qui a juré de trouver la corruption à sa source. Certains de ses proches furent sauvés d'un {link:furbolgs}furbolg{/link} corrompu sur {link:teldrassil}Teldrassil{/link}. Depuis ce jour, il a fait le vœu qu'aucun autre membre de son peuple ne souffre de la même manière, et il surveille de près les furbolgs de {link:darkshore}Sombrivage{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Terenthis fut parmi les premiers à montrer combien le danger s'était approché. Ses éclaireurs trouvèrent les camps {link:blackwood-furbolgs}Noirbois{/link} corrompus en vue d'{link:auberdine}Auberdine{/link}. Il est aussi l'ami de ceux qui vivent seuls dans la nature, et un ami dans le besoin le trouve toujours prêt.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoya des éclaireurs trouver un camp de furbolgs corrompus, et des combattants pour en éclaircir les rangs.
• Il confectionna une cape enchantée de peaux de rôdeurs de lune qui permettait à son porteur de marcher sans être vu des bêtes de {link:darkshore}Sombrivage{/link}.
• Il ramena {link:volcor}Volcor{/link} de la {link:blackwood-den}Tanière des Noirbois{/link}.
• Il envoie ses découvertes à l'ancien, {link:thundris-windweaver}Thundris Windweaver{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Quelle est l'ampleur de la menace ?",
			hint = "Trouvez un camp de furbolgs corrompus près d'Auberdine.",
			text = [=[Le camp au sud d'{link:auberdine}Auberdine{/link} était pire que Terenthis ne l'avait craint. Les {link:blackwood-furbolgs}Noirbois{/link} étaient corrompus, et ils étaient proches. Il dit à Auberdine de se préparer à ce qui devait venir. Il dit aussi à ceux qui s'y étaient battus de ne pas se lamenter. Ils avaient réduit la menace, même si la gangremousse empoisonnait encore la terre.]=],
		},
		{
			title = "Un maître perdu",
			hint = "Répondez à l'appel de la bête venue seule à Auberdine.",
			text = [=[{link:grimclaw}Grimclaw{/link} arriva à {link:auberdine}Auberdine{/link} sans son maître. Terenthis comprit aussitôt. {link:volcor}Volcor{/link} était blessé, quelque part au sud parmi les furbolgs. Il cousit une cape qui cacherait son porteur aux bêtes, et prévint que sa magie cesserait si celui qui la portait faisait autre chose que parler.]=],
		},
	},
	mentions = {
		{ text = "Un maître perdu" },
		{ text = "S'échapper par la force" },
		{ text = "S'échapper par la discrétion" },
		{ text = "{link:thundris-windweaver}Thundris Windweaver{/link}" },
		{
			text = [=[En route pour {link:ashenvale}Orneval{/link}, un appel de la Sentinelle Selarin]=],
		},
	},
	bonds = {
		{ id = "volcor", name = "Volcor", note = "son ami" },
		{ id = "grimclaw", name = "Grimclaw", note = "le compagnon de Volcor" },
		{ id = "thundris-windweaver", name = "Thundris Windweaver", note = "l'ancien auquel il rend compte" },
		{ id = "blackwood-furbolgs", name = "Furbolgs Noirbois", note = "la corruption qu'il surveille" },
	},
})

Translate("frFR", "onu", {
	title = "Onu",
	subtitle = "Ancien du savoir",
	found = "Le Bosquet des Anciens, au sud de Sombrivage",
	hint = [=[Cherchez l'Ancien du savoir dans le bosquet près des montagnes du sud.]=],
	allegiance = "Les Anciens · Bosquet des Anciens",
	sections = {
		{
			title = "Résumé",
			text = [=[Onu est un Ancien du savoir, l'un des grands esprits de la forêt, et il garde le {link:grove-of-the-ancients}Bosquet des Anciens{/link} au sud de {link:darkshore}Sombrivage{/link}. Il parle lentement, avec de longues pauses, et il ne se presse pas. Il sait que toute chose arrive en son temps.]=],
		},
		{
			title = "Importance",
			text = [=[Onu est la mémoire de {link:darkshore}Sombrivage{/link}. Il sait ce que vénèrent les cultistes du {link:twilight-s-hammer}Marteau du crépuscule{/link}, et il sait où tomba l'un de leurs anciens seigneurs. Les druides et les érudits d'{link:auberdine}Auberdine{/link} lui soumettent leurs questions les plus graves, et l'archidruide {link:fandral-staghelm}Fandral Staghelm{/link} lui envoie des messages depuis {link:darnassus}Darnassus{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoya des guetteurs au {link:the-master-s-glaive}Glaive du Maître{/link} et apprit que le {link:twilight-s-hammer}Marteau du crépuscule{/link} s'y trouvait.
• Il étudia une page arrachée au tome du culte et y sentit la magie des anciens.
• Il rassembla des reliques de {link:ruins-of-mathystra}Mathystra{/link} pour apprendre comment le culte se sert de la magie elfique.
• Il parle de {link:malfurion-stormrage}shan'do Stormrage{/link} comme de celui qui comprenait la patience de la forêt.]=],
		},
	},
	chapters = {
		{
			title = "Le Glaive du Maître",
			hint = "Rendez-vous au Glaive du Maître à la demande de l'Ancien.",
			text = [=[Onu trouvait étrange que les nagas soient venus à {link:darkshore}Sombrivage{/link}. Il trouvait plus étrange encore que le {link:twilight-s-hammer}Marteau du crépuscule{/link} soit venu. Quand ses craintes furent confirmées, il parla de l'ancien seigneur empalé au Glaive. Ce seigneur est mort. Sa puissance, peut-être, ne l'est pas.]=],
		},
		{
			title = "Les pages des anciens",
			hint = "Apportez à l'Ancien ce qui fut pris au camp du culte.",
			text = [=[Les griffonnages arrachés au Tome du crépuscule renfermaient une magie chaotique, et sous elle se trouvait une écriture elfique. Le culte se servait d'une antique sorcellerie elfique pour ramener ses anciens maîtres dans le monde. Onu entreprit d'apprendre comment, avant que ses ennemis ne puissent achever ce qu'ils avaient commencé.]=],
		},
		{
			title = "L'escalier sous Mathystra",
			hint = "Apportez à l'Ancien ce qui resta du gardien de Mathystra.",
			text = [=[Quand le globe d'eau trouble fut déposé devant lui, Onu montra quelque chose de proche de la surprise. Il y avait un escalier sous {link:ruins-of-mathystra}Mathystra{/link}, et un gardien veillait sur lui. Il dit seulement qu'il devait parler aux autres Anciens, et qu'il était heureux que l'escalier ait été trouvé avant que les nagas ou le culte ne le trouvent.]=],
		},
	},
	mentions = {
		{
			text = [=[Onu, appelé par {link:barithras-moonshade}Barithras Moonshade{/link}]=],
		},
		{ text = "Le camp du crépuscule" },
		{
			text = [=[Le {link:grove-of-the-ancients}Bosquet des Anciens{/link}, un message de {link:fandral-staghelm}Fandral Staghelm{/link}]=],
		},
	},
	bonds = {
		{ id = "arbal", name = "Arbal", note = "se tient avec lui dans le bosquet" },
		{ id = "barithras-moonshade", name = "Barithras Moonshade", note = "écoute ses avertissements" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "lui envoie des nouvelles" },
		{ id = "baron-marinous", name = "Baron Marinous", note = "le gardien de Mathystra" },
	},
})

Translate("frFR", "sentinel-glynda-nal-shea", {
	title = "Sentinelle Glynda Nal'Shea",
	subtitle = "Sentinelle d'Auberdine",
	found = "Auberdine",
	hint = "Parlez à la Sentinelle qui paie les primes d'Auberdine.",
	allegiance = "Sentinelles · Auberdine",
