			title = "Résumé",
			text = [=[La Sentinelle Glynda Nal'Shea veille sur la sécurité d'{link:auberdine}Auberdine{/link}, et elle en a une vision sévère. Là où d'autres révèrent encore les séléniens, elle ne voit que leur nombre croissant et leur colère. Elle paie les primes affichées par le conseil du village, et elle veut des réponses sur le cristal rouge des collines de l'est.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle fit trouver le cristal rouge et le fit éprouver avec de l'eau du puits de lune. Il contenait des os et la moitié d'une mâchoire.
• Elle paya la prime sur le {link:murlocs}murloc{/link} {link:murkdeep}Murkdeep{/link}.
• Elle paya la prime sur la chouette noire {link:jai-vhanel}Jai'vhanel{/link}, et regretta qu'aucune autre voie n'ait été trouvée.]=],
		},
	},
	mentions = {
		{ text = "Le cristal rouge" },
		{ text = "Comme l'eau qui tombe en cascade" },
		{ text = "Les fragments à l'intérieur" },
		{ text = "AVIS DE RECHERCHE : {link:murkdeep}Murkdeep{/link} !" },
		{ text = "AVIS DE RECHERCHE : {link:jai-vhanel}Jai'vhanel{/link}" },
	},
	bonds = {
		{ id = "murkdeep", name = "Murkdeep", note = "le murloc dont elle voulait la mort" },
		{ id = "jai-vhanel", name = "Jai'vhanel", note = "une gardienne devenue folle" },
	},
})

Translate("frFR", "tharnariun-treetender", {
	title = "Tharnariun Treetender",
