	sections = {
		{
			title = "Résumé",
			text = [=[Tharnariun Treetender a tenté de guérir le fléau qui frappe les ours des chardons de {link:darkshore}Sombrivage{/link}. Ces bêtes jadis nobles sont devenues enragées. Il construisit un piège de lumière pour les apaiser, dans l'espoir d'en soigner une. Le remède échoua. Il doit maintenant ordonner la mort des créatures qu'il voulait sauver, et cela l'afflige.]=],
