			text = [=[Hollee est une naine de la {link:explorers-league}Ligue des explorateurs{/link}. Ce fut un honneur, dit-elle, d'être placée sous les ordres du grand prospecteur {link:prospector-remtravel}Remtravel{/link}. Ce fut un moindre honneur de voir des golems surgir du sol sur leur chantier pendant que le prospecteur continuait à brosser des pierres. Elle courut chercher de l'aide à {link:auberdine}Auberdine{/link}. Elle n'a pas oublié une camarade de ses années d'études, aujourd'hui dans les {link:wetlands}Paluns{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle fuit les golems des {link:remtravel-s-excavation}Excavations de Remtravel{/link} pour chercher de l'aide.
• Elle fit parvenir le fossile du prospecteur à la Ligue.
• Elle écrivit un mot à son vieil ami {link:tarrel-rockweaver}Tarrel Rockweaver{/link}, près du {link:menethil-harbor}Port de Menethil{/link}.]=],
		},
	},
	mentions = {
		{ text = "Des ennuis à {link:darkshore}Sombrivage{/link} ?" },
		{ text = "Le prospecteur distrait" },
		{ text = "Le prospecteur distrait" },
		{ text = "Amour non partagé" },
	},
	bonds = {
		{ id = "prospector-remtravel", name = "Prospecteur Remtravel", note = "son maître" },
	},
})

