	subtitle = "La chouette noire",
	found = "Au nord d'Ameth’Aran, près du pied des montagnes",
	hint = "Affrontez la chouette noire qui chasse au nord d'Ameth’Aran.",
	allegiance = "La nature sauvage",
	aliases = { "Swordfeather" },
	sections = {
		{
			title = "Résumé",
			text = [=[Jai'vhanel, appelée Swordfeather, est une grande chouette aux plumes noires comme le jais. Pendant longtemps, elle fut une gardienne des terres autour d'{link:ameth-aran}Ameth’Aran{/link}. Puis elle devint folle, et elle se mit à attaquer les voyageurs sur la route d'{link:auberdine}Auberdine{/link}. Nul ne sait ce qui l'y poussa. Les {link:sentinels}Sentinelles{/link} mirent sa tête à prix.]=],
		},
		{ title = "Ce que l'on ignore", text = "La cause de sa folie est inconnue." },
		{
			title = "Importance",
			text = [=[Les {link:sentinels}Sentinelles{/link} ne l'ont pas chassée de bon cœur. Sa chute est un signe de plus que quelque chose s'est déréglé chez les créatures de {link:darkshore}Sombrivage{/link}, des ours de la forêt aux oiseaux des collines.]=],
		},
	},
	mentions = {
		{ text = "AVIS DE RECHERCHE : Jai'vhanel" },
	},
	bonds = {
		{ id = "sentinel-glynda-nal-shea", name = "Sentinelle Glynda Nal'Shea", note = "a mis sa tête à prix" },
	},
})

Translate("frFR", "lord-sinslayer", {
	title = "Seigneur Sinslayer",
	subtitle = "Naga des Chutes de la Bondissante",
	found = "La grotte derrière les Chutes de la Bondissante",
	hint = [=[Affrontez le seigneur naga tapi dans la grotte derrière les Chutes de la Bondissante.]=],
	allegiance = "Nagas",
	aliases = { "Sinslayer" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le seigneur Sinslayer mène les {link:naga}nagas{/link} qui ont pris la grotte derrière les {link:cliffspring-falls}Chutes de la Bondissante{/link}. Les Anciens sentirent le mal dans cette grotte avant qu'aucun elfe ne l'ait vu. Les chutes donnent à {link:darkshore}Sombrivage{/link} une grande part de son eau potable, et le poison qui en coule désormais a rendu malades les cerfs de tout le pays.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[On sait peu de choses de Sinslayer au-delà de son nom et de son repaire.]=],
		},
		{
			title = "Importance",
			text = [=[La grotte de Sinslayer est plus proche d'{link:auberdine}Auberdine{/link} que {link:ruins-of-mathystra}Mathystra{/link}. Sa présence montre que les nagas ne se contentent plus des vieilles ruines du nord-est.]=],
		},
	},
	bonds = {
		{ id = "barithras-moonshade", name = "Barithras Moonshade", note = "fut averti au sujet de sa grotte" },
	},
})

Translate("frFR", "murkdeep", {
	title = "Murkdeep",
	subtitle = "Terreur des Greymist",
	found = "Un camp de murlocs sur la côte au sud d'Auberdine",
	hint = "Affrontez le murloc qui garde les huttes de la côte sud.",
	allegiance = "Murlocs Greymist",
	sections = {
		{
			title = "Résumé",
			text = [=[Murkdeep est un {link:murlocs}murloc{/link} de la tribu Greymist qui garde un camp de huttes sur la côte au sud d'{link:auberdine}Auberdine{/link}. Il a tué au moins une Sentinelle. On le soupçonne aussi d'avoir coulé deux navires de marchandises au large de la côte. Le conseil du village a mis sa tête à prix, et les habitants disent qu'ils dormiront plus tranquilles quand la prime aura été payée.]=],
		},
		{
			title = "Importance",
			text = [=[Murkdeep est la raison pour laquelle les pêcheurs d'{link:auberdine}Auberdine{/link} gardent leurs bateaux à terre, et la raison pour laquelle les marchandises venues de la mer arrivent en retard, ou pas du tout.]=],
		},
	},
	mentions = {
		{ text = "AVIS DE RECHERCHE : Murkdeep !" },
	},
	bonds = {
		{ id = "sentinel-glynda-nal-shea", name = "Sentinelle Glynda Nal'Shea", note = "paie la prime" },
	},
})

Translate("frFR", "kerlonian-evershade", {
	title = "Kerlonian Evershade",
	subtitle = "Druide de la Griffe",
	found = "Près du Bosquet des Anciens",
	hint = [=[Trouvez le druide ensommeillé qui a perdu ses affaires près du bosquet du sud.]=],
	allegiance = "Druides de la Griffe",
	aliases = { "Kerlonian" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kerlonian Evershade est un Druide de la Griffe qui s'est récemment éveillé du {link:emerald-dream}Rêve d'émeraude{/link}. Il est somnolent depuis. Il partit pour le {link:maestra-s-post}Poste de Maestra{/link} afin de rencontrer {link:liladris-moonriver}Liladris Moonriver{/link}, s'arrêta pour une courte sieste, et perdit ses affaires. Un cor rangé dans son coffre le réveillera s'il s'assoupit de nouveau.]=],
		},
		{
			title = "Hauts faits",
